const embeddingItems = $input.all();
const sourceItems = $('Parse JSONL Chunks').all();

const EXPECTED_VECTOR_SIZE = 1024;

if (embeddingItems.length !== sourceItems.length) {
  throw new Error(
    `عدد نتائج Cohere (${embeddingItems.length}) لا يساوي عدد Chunks (${sourceItems.length})`
  );
}

if (sourceItems.length === 0) {
  throw new Error('لم يتم العثور على أي Chunks للمعالجة.');
}

const results = [];

/*
 * إنشاء UUID ثابت Deterministic من chunk_id.
 *
 * الهدف:
 * - نفس chunk_id ينتج دائمًا نفس point_id.
 * - مناسب لإعادة تشغيل ingestion بدون إنشاء نسخة مكررة.
 * - أقوى بكثير من الـ 32-bit hash السابق.
 * - الصيغة الناتجة مقبولة كـ UUID في Qdrant.
 *
 * ملاحظة:
 * هذه ليست دالة تشفير أمني، وإنما مولّد UUID ثابت
 * للاستخدام كمعرّف داخلي في Qdrant.
 */
function createDeterministicUuid(input) {

  const text = String(input);

  let h1 = 0xdeadbeef ^ text.length;
  let h2 = 0x41c6ce57 ^ text.length;
  let h3 = 0xc0decafe ^ text.length;
  let h4 = 0x1234567 ^ text.length;

  for (let i = 0; i < text.length; i++) {

    const ch = text.charCodeAt(i);

    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
    h3 = Math.imul(h3 ^ ch, 2246822507);
    h4 = Math.imul(h4 ^ ch, 3266489909);
  }

  h1 =
    Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^
    Math.imul(h2 ^ (h2 >>> 13), 3266489909);

  h2 =
    Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^
    Math.imul(h3 ^ (h3 >>> 13), 3266489909);

  h3 =
    Math.imul(h3 ^ (h3 >>> 16), 2246822507) ^
    Math.imul(h4 ^ (h4 >>> 13), 3266489909);

  h4 =
    Math.imul(h4 ^ (h4 >>> 16), 2246822507) ^
    Math.imul(h1 ^ (h1 >>> 13), 3266489909);

  const hex =
    (h1 >>> 0).toString(16).padStart(8, '0') +
    (h2 >>> 0).toString(16).padStart(8, '0') +
    (h3 >>> 0).toString(16).padStart(8, '0') +
    (h4 >>> 0).toString(16).padStart(8, '0');

  // UUID v4-compatible formatting
  return (
    hex.slice(0, 8) + '-' +
    hex.slice(8, 12) + '-' +
    '4' + hex.slice(13, 16) + '-' +
    '8' + hex.slice(17, 20) + '-' +
    hex.slice(20, 32)
  );
}


for (let i = 0; i < embeddingItems.length; i++) {

  const embeddingResponse = embeddingItems[i].json;
  const original = sourceItems[i].json;

  // ==========================================
  // 1. التحقق من Vector
  // ==========================================

  const vector =
    embeddingResponse.embeddings?.float?.[0];

  if (!Array.isArray(vector)) {
    throw new Error(
      `لم يتم العثور على Vector صالح للـ Chunk رقم ${i + 1}`
    );
  }

  if (vector.length !== EXPECTED_VECTOR_SIZE) {
    throw new Error(
      `حجم Vector غير صحيح للـ Chunk رقم ${i + 1}: ` +
      `${vector.length} بدلاً من ${EXPECTED_VECTOR_SIZE}`
    );
  }


  // ==========================================
  // 2. قراءة Chunk
  // ==========================================

  const chunkId =
    String(original.id || '').trim();

  if (!chunkId) {
    throw new Error(
      `لا يوجد id للـ Chunk رقم ${i + 1}`
    );
  }

  const content =
    String(original.text || '').trim();

  if (!content) {
    throw new Error(
      `النص فارغ في الـ Chunk: ${chunkId}`
    );
  }


  // ==========================================
  // 3. Metadata
  // ==========================================

  const metadata =
    original.metadata &&
    typeof original.metadata === 'object'
      ? original.metadata
      : {};


  const sourceTitle =
    String(metadata.source_title || '').trim();

  if (!sourceTitle) {
    throw new Error(
      `source_title مفقود في الـ Chunk: ${chunkId}`
    );
  }


  const sourceType =
    String(metadata.source_type || 'book').trim();


  const language =
    String(metadata.language || 'ar').trim();


  const pdfPages =
    Array.isArray(metadata.pdf_pages)
      ? metadata.pdf_pages
      : [];


  const printedPages =
    Array.isArray(metadata.printed_pages)
      ? metadata.printed_pages
      : [];


  // ==========================================
  // 4. إنشاء Qdrant Point
  // ==========================================

  results.push({

    json: {

      point_id:
        createDeterministicUuid(chunkId),

      chunk_id:
        chunkId,

      vector,

      payload: {

        // ======================================
        // المحتوى
        // ======================================

        content,

        // ======================================
        // هوية المصدر
        // ======================================

        source_title:
          sourceTitle,

        source_type:
          sourceType,

        author:
          metadata.author || '',

        language:
          language,

        document_id:
          metadata.document_id || '',


        // ======================================
        // بنية الكتاب
        // ======================================

        issue_number:
          metadata.issue_number ?? null,

        issue_title:
          metadata.issue_title || '',

        section_title:
          metadata.section_title ||
          metadata.issue_title ||
          '',


        // ======================================
        // الصفحات
        // ======================================

        pdf_pages:
          pdfPages,

        printed_pages:
          printedPages,

        page_start:
          metadata.page_start ??
          (
            printedPages.length
              ? printedPages[0]
              : null
          ),

        page_end:
          metadata.page_end ??
          (
            printedPages.length
              ? printedPages[printedPages.length - 1]
              : null
          ),


        // ======================================
        // هوية Chunk
        // ======================================

        chunk_id:
          chunkId,

        chunk_index:
          metadata.chunk_index ?? null,

        parent_id:
          metadata.parent_id || '',


        // ======================================
        // Lineage / Processing
        // ======================================

        dataset:
          metadata.dataset || '',

        processing_version:
          metadata.processing_version || '',

        rag_ready:
          metadata.rag_ready ?? true,

        docling_refs:
          Array.isArray(metadata.docling_refs)
            ? metadata.docling_refs
            : [],


        // ======================================
        // سياسات جودة المصدر
        // ======================================

        quran_special_font_policy:
          metadata.quran_special_font_policy || ''
      }
    }
  });
}

return results;

