// Evaluate Retrieval Sufficiency
// تقييم أولي لنتائج Qdrant قبل اتخاذ قرار الكفاية

const input = $input.first().json;

// ==========================================
// 1) قراءة نتائج Qdrant
// ==========================================

const points = input.result?.points || [];

if (points.length === 0) {
  return [{
    json: {
      sufficient: false,
      status: "INSUFFICIENT",
      reason: "لم يتم العثور على أي مادة في قاعدة المعرفة.",
      best_score: 0,
      retrieved_count: 0,
      usable_count: 0,
      evidence: []
    }
  }];
}


// ==========================================
// 2) ترتيب النتائج حسب درجة التشابه
// ==========================================

const sortedPoints = [...points].sort(
  (a, b) => Number(b.score || 0) - Number(a.score || 0)
);


// ==========================================
// 3) إزالة النتائج شديدة الضعف فقط
// ==========================================

const MIN_USABLE_SCORE = 0.25;

const usablePoints = sortedPoints.filter(
  point => Number(point.score || 0) >= MIN_USABLE_SCORE
);


// ==========================================
// 4) أخذ أفضل 5 نتائج
// ==========================================

const topResults = usablePoints.slice(0, 5);

const bestScore =
  Number(sortedPoints[0]?.score || 0);


// ==========================================
// 5) إذا لم يبق أي دليل قابل للفحص
// ==========================================

if (topResults.length === 0) {
  return [{
    json: {
      sufficient: false,
      status: "INSUFFICIENT",
      reason:
        "نتائج الاسترجاع ضعيفة جدًا ولا توجد مادة مناسبة لإرسالها للتقييم الدلالي.",
      best_score: bestScore,
      retrieved_count: points.length,
      usable_count: 0,
      evidence: []
    }
  }];
}


// ==========================================
// 6) تجهيز الأدلة
// يدعم Metadata القديم والجديد
// ==========================================

const evidence = topResults.map(point => {

  const p = point.payload || {};

  const printedPages =
    Array.isArray(p.printed_pages)
      ? p.printed_pages
      : [];

  const pdfPages =
    Array.isArray(p.pdf_pages)
      ? p.pdf_pages
      : [];

  return {

    // درجة التشابه
    score:
      Number(point.score || 0),

    // النص المسترجع
    content:
      p.content || "",


    // ======================================
    // بيانات المصدر
    // ======================================

    source_type:
      p.source_type || "book",

    source_title:
      p.source_title ||
      p.book_title ||
      p.source_name ||
      "",

    // للتوافق مع النظام القديم
    book_title:
      p.book_title ||
      p.source_title ||
      p.source_name ||
      "",

    source_name:
      p.source_name ||
      p.source_title ||
      p.book_title ||
      "",

    document_id:
      p.document_id || "",


    // ======================================
    // المسألة / القسم
    // ======================================

    issue_number:
      p.issue_number ?? null,

    issue_title:
      p.issue_title || "",

    section_title:
      p.section_title ||
      p.issue_title ||
      "",


    // ======================================
    // الصفحات الجديدة
    // ======================================

    printed_pages:
      printedPages,

    pdf_pages:
      pdfPages,


    // ======================================
    // دعم حقول الصفحات القديمة
    // ======================================

    page_start:
      p.page_start ??
      (
        printedPages.length > 0
          ? printedPages[0]
          : null
      ),

    page_end:
      p.page_end ??
      (
        printedPages.length > 0
          ? printedPages[printedPages.length - 1]
          : null
      ),


    // ======================================
    // بيانات Chunk
    // ======================================

    chunk_id:
      p.chunk_id || "",

    chunk_index:
      p.chunk_index ?? null,

    parent_id:
      p.parent_id || "",

    docling_refs:
      Array.isArray(p.docling_refs)
        ? p.docling_refs
        : [],


    // ======================================
    // Metadata الجديدة
    // ======================================

    language:
      p.language || "ar",

    dataset:
      p.dataset || "",

    processing_version:
      p.processing_version || "",

    rag_ready:
      p.rag_ready ?? null
  };
});


// ==========================================
// 7) النتيجة
// ==========================================

return [{
  json: {

    sufficient: true,

    status: "READY_FOR_SEMANTIC_EVALUATION",

    reason:
      "تم العثور على نتائج قابلة للفحص. يجب تقييم كفايتها دلاليًا بناءً على محتواها، وليس على درجة التشابه وحدها.",

    best_score:
      bestScore,

    retrieved_count:
      points.length,

    usable_count:
      topResults.length,

    evidence
  }
}];

