parameters.jsCode:
const input = $input.first().json;

// ==========================================
// 1) قراءة ناتج Evidence Judge
// ==========================================

let raw = input.text || input.output || '';

raw = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let decision;

try {
  decision = JSON.parse(raw);
} catch (error) {
  throw new Error(
    'تعذر قراءة قرار Evidence Judge كـ JSON.\n\nالناتج:\n' + raw
  );
}


// ==========================================
// 2) التحقق من القرار
// ==========================================

const allowedDecisions = [
  'SUPPORTED',
  'NEEDS_EXTERNAL_SEARCH',
  'NEEDS_HUMAN_REVIEW'
];

if (!allowedDecisions.includes(decision.decision)) {
  throw new Error(
    'قيمة decision غير صحيحة: ' + decision.decision
  );
}


// ==========================================
// 3) استرجاع الأدلة الأصلية من مرحلة RAG
// ==========================================

let retrievalData = {};

try {
  retrievalData =
    $('Evaluate Retrieval Sufficiency').first().json;
} catch (error) {
  retrievalData = {};
}

const allEvidence = Array.isArray(retrievalData.evidence)
  ? retrievalData.evidence
  : [];


// ==========================================
// 4) اختيار الأدلة التي أوصى بها Evidence Judge
// ==========================================

const recommendedIndexes =
  Array.isArray(decision.recommended_evidence_indexes)
    ? decision.recommended_evidence_indexes
    : [];

/*
  نحاول استخدام الأدلة التي اختارها المقيّم.

  ندعم الحالتين:
  1,2,3  ← ترقيم بشري يبدأ من 1
  0,1,2  ← index يبدأ من 0
*/

let selectedEvidence = allEvidence;

if (recommendedIndexes.length > 0) {

  const numericIndexes = recommendedIndexes
    .map(value => Number(value))
    .filter(value => Number.isInteger(value));

  const usesZeroBased =
    numericIndexes.includes(0);

  const filtered = numericIndexes
    .map(index => {
      const actualIndex =
        usesZeroBased ? index : index - 1;

      return allEvidence[actualIndex];
    })
    .filter(Boolean);

  if (filtered.length > 0) {
    selectedEvidence = filtered;
  }
}


// ==========================================
// 5) إخراج القرار مع الأدلة
// ==========================================

return [{
  json: {

    evidence_sufficient:
      decision.evidence_sufficient === true,

    confidence:
      Number(decision.confidence || 0),

    decision:
      decision.decision,

    needs_external_search:
      decision.needs_external_search === true,

    needs_human_review:
      decision.needs_human_review === true,

    reason:
      decision.reason || '',

    supported_points:
      Array.isArray(decision.supported_points)
        ? decision.supported_points
        : [],

    missing_points:
      Array.isArray(decision.missing_points)
        ? decision.missing_points
        : [],

    recommended_evidence_indexes:
      recommendedIndexes,

    // الأدلة المختارة للإجابة
    combined_evidence:
      selectedEvidence,

    // الاحتفاظ بكل النتائج أيضًا للتتبع
    all_retrieved_evidence:
      allEvidence,

    best_score:
      Number(retrievalData.best_score || 0),

    retrieved_count:
      Number(retrievalData.retrieved_count || 0),

    usable_count:
      Number(retrievalData.usable_count || 0)
  }
}];

