const item = $input.first().json;

// استرجاع السياق الأصلي من Prepare Approved Sources
let sourceData = {};

try {
  sourceData = $('Prepare Approved Sources').first().json;
} catch (error) {
  sourceData = {};
}

// قراءة مخرجات Select Approved Sources
let raw = item.text ?? item.output ?? '';

if (typeof raw === 'string') {
  raw = raw
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');
}

let parsed;

try {
  parsed = typeof raw === 'object'
    ? raw
    : JSON.parse(raw);
} catch (error) {
  throw new Error(
    'تعذر قراءة مخرجات Select Approved Sources كـ JSON.\n\n' +
    'الخطأ: ' + error.message +
    '\n\nالناتج الخام:\n' + String(raw)
  );
}

// القرارات المسموح بها فقط
const allowedDecisions = [
  'SOURCES_SELECTED',
  'NO_SUITABLE_SOURCE'
];

let decision = String(
  parsed.decision ?? ''
).trim().toUpperCase();

if (!allowedDecisions.includes(decision)) {
  throw new Error(
    'قيمة decision غير صحيحة في Select Approved Sources: ' +
    decision
  );
}

// تنظيف المصادر المختارة
const selectedSources = Array.isArray(parsed.selected_sources)
  ? parsed.selected_sources
      .filter(source => source && typeof source === 'object')
      .map(source => ({
        row_number: source.row_number ?? '',
        category: String(
          source.category ?? ''
        ).trim(),
        approved_content: String(
          source.approved_content ?? ''
        ).trim(),
        usage_rule: String(
          source.usage_rule ?? ''
        ).trim(),
        reason: String(
          source.reason ?? ''
        ).trim()
      }))
  : [];

// حماية من تناقض قرار النموذج
if (
  decision === 'SOURCES_SELECTED' &&
  selectedSources.length === 0
) {
  throw new Error(
    'Select Approved Sources أعاد SOURCES_SELECTED ولكن بدون أي مصدر.'
  );
}

if (decision === 'NO_SUITABLE_SOURCE') {
  return [{
    json: {
      question: sourceData.question ?? '',

      chat_id: sourceData.chat_id ?? null,
      message_id: sourceData.message_id ?? null,
      user_id: sourceData.user_id ?? null,
      target_language:
        sourceData.target_language ?? 'ti',

      decision: 'NO_SUITABLE_SOURCE',
      selected_sources: [],
      search_intent: '',

      approved_sources_count:
        Number(sourceData.approved_sources_count ?? 0)
    }
  }];
}

// حالة وجود مصادر مناسبة
return [{
  json: {
    question: sourceData.question ?? '',

    chat_id: sourceData.chat_id ?? null,
    message_id: sourceData.message_id ?? null,
    user_id: sourceData.user_id ?? null,
    target_language:
      sourceData.target_language ?? 'ti',

    decision: 'SOURCES_SELECTED',

    selected_sources: selectedSources,

    search_intent: String(
      parsed.search_intent ?? ''
    ).trim(),

    approved_sources_count:
      Number(sourceData.approved_sources_count ?? 0)
  }
}];

const data = $input.first().json;

const selectedSources = Array.isArray(data.selected_sources)
  ? data.selected_sources
  : [];

const domains = new Set();
const urls = new Set();

function extractDomainsAndUrls(text) {
  if (!text) return;

  const value = String(text);

  // تقسيم النص إلى أجزاء بناءً على الفراغات وعلامات الترقيم العربية
  const parts = value.split(/[\s،؛,;()]+/);

  for (let part of parts) {
    if (!part) continue;

    part = part
      .trim()
      .replace(/[.،,؛;:]+$/g, '');

    // تجاهل أي جزء لا يحتوي نقطة
    if (!part.includes('.')) continue;

    // إزالة البروتوكول إن وجد
    let cleaned = part
      .replace(/^https?:\/\//i, '')
      .replace(/^www\./i, '');

    // استخراج domain من أول جزء قبل /
    const domain = cleaned
      .split('/')[0]
      .split('?')[0]
      .split('#')[0]
      .toLowerCase()
      .trim();

    // تحقق بسيط وآمن من شكل النطاق
    const validDomain =
      /^[a-z0-9-]+(?:\.[a-z0-9-]+)+$/i.test(domain);

    if (!validDomain) continue;

    domains.add(domain);

    // إذا كان هناك path مثل:
    // dorar.net/hadith
    // dorar.net/aqeeda
    const slashIndex = cleaned.indexOf('/');

    if (slashIndex !== -1) {
      const path = cleaned.substring(slashIndex);

      if (path && path !== '/') {
        urls.add(`https://${domain}${path}`);
      }
    }
  }
}

// فحص كل مصدر اختاره النظام
for (const source of selectedSources) {
  extractDomainsAndUrls(source.approved_content);
  extractDomainsAndUrls(source.usage_rule);
}

const approvedDomains = [...domains];
const approvedUrls = [...urls];

const canSearch =
  data.decision === 'SOURCES_SELECTED' &&
  selectedSources.length > 0 &&
  approvedDomains.length > 0;

return [{
  json: {
    question: data.question ?? '',

    chat_id: data.chat_id ?? null,
    message_id: data.message_id ?? null,
    user_id: data.user_id ?? null,
    target_language: data.target_language ?? 'ti',

    decision: data.decision ?? '',
    search_intent: data.search_intent ?? '',

    selected_sources: selectedSources,

    approved_domains: approvedDomains,
    approved_urls: approvedUrls,

    approved_domains_count: approvedDomains.length,
    approved_urls_count: approvedUrls.length,

    can_search: canSearch
  }
}];

// =============================================
// Parse Approved Search
// يدعم تعدد النتائج القادمة من Search
// ويحافظ على approved_domains الأصلية
// =============================================

const inputItems = $input.all();

// ---------------------------------
// استرجاع السياق الأصلي قبل التقسيم
// ---------------------------------

let searchContext = {};

try {
  searchContext =
    $('Prepare Approved Web Search').first().json;
} catch (error) {
  searchContext = {};
}

// ---------------------------------
// النطاقات المعتمدة
// ---------------------------------

const approvedDomains = Array.isArray(searchContext.approved_domains)
  ? searchContext.approved_domains
      .map(domain =>
        String(domain ?? '')
          .trim()
          .toLowerCase()
          .replace(/^www\./i, '')
      )
      .filter(Boolean)
  : [];

// ---------------------------------
// تحليل جميع مخرجات Search
// ---------------------------------

const allResults = [];

for (const inputItem of inputItems) {

  const item = inputItem.json ?? {};

  // ---------------------------------
  // الحالة 1:
  // Search يعيد نتائج مباشرة
  // ---------------------------------

  if (Array.isArray(item.results)) {

    for (const result of item.results) {

      if (!result || typeof result !== 'object') {
        continue;
      }

      const url = String(
        result.url ??
        result.link ??
        ''
      ).trim();

      const content = String(
        result.content ??
        result.raw_content ??
        result.snippet ??
        ''
      ).trim();

      const title = String(
        result.title ?? ''
      ).trim();

      if (!url || !content) {
        continue;
      }

      allResults.push({
        title,
        url,
        content,
        source_domain: '',
        tavily_score:
          typeof result.score === 'number'
            ? result.score
            : null
      });
    }

    continue;
  }

  // ---------------------------------
  // الحالة 2:
  // Approved Sources Search Agent
  // يعيد JSON داخل output/text
  // ---------------------------------

  let raw =
    item.output ??
    item.text ??
    '';

  if (!raw) {
    continue;
  }

  if (typeof raw === 'string') {
    raw = raw
      .trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '');
  }

  let parsed;

  try {
    parsed =
      typeof raw === 'object'
        ? raw
        : JSON.parse(raw);
  } catch (error) {
    throw new Error(
      'تعذر قراءة إحدى نتائج البحث كـ JSON.\n\n' +
      'الخطأ: ' +
      error.message +
      '\n\nالناتج الخام:\n' +
      String(raw)
    );
  }

  if (
    String(parsed.search_status ?? '')
      .trim()
      .toUpperCase() !== 'FOUND'
  ) {
    continue;
  }

  if (!Array.isArray(parsed.results)) {
    continue;
  }

  for (const result of parsed.results) {

    if (!result || typeof result !== 'object') {
      continue;
    }

    const url = String(
      result.url ??
      result.link ??
      ''
    ).trim();

    const content = String(
      result.content ??
      result.raw_content ??
      result.snippet ??
      ''
    ).trim();

    const title = String(
      result.title ?? ''
    ).trim();

    if (!url || !content) {
      continue;
    }

    allResults.push({
      title,
      url,
      content,
      source_domain: String(
        result.source_domain ?? ''
      ).trim(),
      tavily_score:
        typeof result.score === 'number'
          ? result.score
          : (
              typeof result.tavily_score === 'number'
                ? result.tavily_score
                : null
            )
    });
  }
}

// ---------------------------------
// إزالة النتائج المكررة حسب URL
// ---------------------------------

const seenUrls = new Set();
const uniqueResults = [];

for (const result of allResults) {

  const key =
    result.url
      .trim()
      .toLowerCase();

  if (!key || seenUrls.has(key)) {
    continue;
  }

  seenUrls.add(key);
  uniqueResults.push(result);
}

// ---------------------------------
// تحديد النتيجة النهائية
// ---------------------------------

const hasResults =
  uniqueResults.length > 0;

// ---------------------------------
// إخراج موحد
// ---------------------------------

return [{
  json: {

    question:
      searchContext.question ?? '',

    chat_id:
      searchContext.chat_id ?? null,

    message_id:
      searchContext.message_id ?? null,

    user_id:
      searchContext.user_id ?? null,

    target_language:
      searchContext.target_language ?? 'ti',

    search_intent:
      searchContext.search_intent ?? '',

    search_status:
      hasResults
        ? 'FOUND'
        : 'NOT_FOUND',

    external_evidence:
      hasResults
        ? uniqueResults
        : [],

    external_evidence_count:
      uniqueResults.length,

    selected_sources:
      Array.isArray(searchContext.selected_sources)
        ? searchContext.selected_sources
        : [],

    approved_domains:
      approvedDomains,

    approved_urls:
      Array.isArray(searchContext.approved_urls)
        ? searchContext.approved_urls
        : [],

    needs_human_review:
      !hasResults
  }
}];

const current = $input.first().json;

// ---------------------------------
// السؤال الأصلي وسياق Telegram
// ---------------------------------

let incoming = {};

try {
  incoming =
    $('Prepare Incoming Question')
      .first()
      .json;
} catch (error) {
  incoming = {};
}

// ---------------------------------
// بيانات الاسترجاع الداخلي RAG
// إن كانت متاحة
// ---------------------------------

let ragData = {};

try {
  ragData =
    $('Evaluate Retrieval Sufficiency')
      .first()
      .json;
} catch (error) {
  ragData = {};
}

// ---------------------------------
// تحديد السؤال وبيانات صاحب الطلب
// ---------------------------------

const question =
  current.question ??
  incoming.question ??
  '';

const chatId =
  current.chat_id ??
  incoming.chat_id ??
  null;

const userId =
  current.user_id ??
  incoming.user_id ??
  null;

const messageId =
  current.message_id ??
  incoming.message_id ??
  null;

const targetLanguage =
  current.target_language ??
  incoming.target_language ??
  'ti';

// ---------------------------------
// إنشاء رقم مراجعة موحد
// REV- وليس review_
// ---------------------------------

const reviewId =
  `REV-${chatId}-${messageId}`;

// ---------------------------------
// أدلة RAG الداخلية
// ---------------------------------

const ragEvidence =
  Array.isArray(
    ragData.evidence
  )
    ? ragData.evidence
    : [];

// ---------------------------------
// الأدلة الخارجية إن وجدت
// ---------------------------------

const externalEvidence =
  Array.isArray(
    current.external_evidence
  )
    ? current.external_evidence
    : [];

// ---------------------------------
// جميع الأدلة المتاحة للمراجع
// ---------------------------------

let combinedEvidence = [];

if (
  Array.isArray(current.combined_evidence) &&
  current.combined_evidence.length > 0
) {

  combinedEvidence =
    current.combined_evidence;

} else if (
  externalEvidence.length > 0
) {

  combinedEvidence =
    externalEvidence;

} else {

  combinedEvidence =
    ragEvidence;
}

// ---------------------------------
// تحديد حالة RAG
// ---------------------------------

const ragStatus =
  ragData.status ??
  ragData.rag_status ??
  (
    ragEvidence.length > 0
      ? 'EVIDENCE_RETRIEVED'
      : 'NO_USABLE_EVIDENCE'
  );

const ragBestScore =
  ragData.best_score ??
  ragData.rag_best_score ??
  null;

// ---------------------------------
// تحديد حالة البحث الخارجي
// ---------------------------------

const externalSearchStatus =
  current.search_status ??
  (
    externalEvidence.length > 0
      ? 'FOUND'
      : 'NOT_FOUND'
  );

// ---------------------------------
// تحديد سبب الإحالة
// ---------------------------------

let escalationReason =
  current.decision_reason ??
  current.reason ??
  '';

if (!escalationReason) {

  if (
    current.validation_status ===
    'NO_VALID_APPROVED_RESULTS'
  ) {

    escalationReason =
      'لم يعثر النظام على نتائج خارجية صالحة من النطاقات المعتمدة.';

  } else if (
    externalSearchStatus === 'NOT_FOUND'
  ) {

    escalationReason =
      'لم يعثر النظام على أدلة كافية في قاعدة المعرفة الداخلية أو المصادر الخارجية المعتمدة.';

  } else {

    escalationReason =
      'لم يحصل النظام على أدلة كافية وموثوقة تسمح بإنتاج إجابة نهائية آلية.';
  }
}

// ---------------------------------
// رسالة المراجع البشري
// ---------------------------------

const reviewMessage =
`🧑‍💼 طلب مراجعة بشرية

رقم المراجعة:
${reviewId}

سؤال المدعو:
${question}

سبب الإحالة:
${escalationReason}

حالة البحث في قاعدة المعرفة:
${ragStatus}

أفضل درجة استرجاع:
${ragBestScore ?? 'غير متوفر'}

حالة البحث في المصادر الخارجية:
${externalSearchStatus}

عدد الأدلة الخارجية المقبولة:
${externalEvidence.length}

المطلوب من المراجع:
أرسل المادة العلمية الموثوقة التي ينبغي أن تعتمد عليها الإجابة.

لا يلزمك صياغة الإجابة النهائية أو ترجمتها؛ سيتولى النظام الصياغة والتحقق والترجمة تلقائيًا.

ابدأ ردك برقم المراجعة التالي:
${reviewId}`;

// ---------------------------------
// الإخراج
// ---------------------------------

return [{
  json: {

    review_id:
      reviewId,

    question:
      question,

    requester_chat_id:
      chatId,

    requester_user_id:
      userId,

    requester_message_id:
      messageId,

    rag_status:
      ragStatus,

    rag_best_score:
      ragBestScore,

    rag_evidence:
      ragEvidence,

    combined_evidence:
      combinedEvidence,

    external_search_status:
      externalSearchStatus,

    external_evidence:
      externalEvidence,

    selected_approved_sources:
      Array.isArray(
        current.selected_sources
      )
        ? current.selected_sources
        : [],

    approved_domains:
      Array.isArray(
        current.approved_domains
      )
        ? current.approved_domains
        : [],

    escalation_reason:
      escalationReason,

    review_status:
      'WAITING_FOR_HUMAN',

    original_target_language:
      targetLanguage,

    review_message:
      reviewMessage
  }
}];

const data = $input.first().json;

const text = String(data.message?.text || '').trim();

const firstLine = text.split('\n')[0].trim();

// نتوقع مثل:
// REV-123456789-125
const match = firstLine.match(/^REV-(\d+)-(\d+)$/i);

if (!match) {
  throw new Error(
    'صيغة رد المراجع غير صحيحة. يجب أن يبدأ الرد بـ REV-chatid-messageid'
  );
}

const chatId = match[1];
const messageId = match[2];

// تحويل الصيغة إلى review_id المخزن في Data Table
const reviewId = `review_${chatId}_${messageId}`;

// كل ما بعد السطر الأول هو المادة العلمية للمراجع
const humanEvidence = text
  .split('\n')
  .slice(1)
  .join('\n')
  .trim();

if (!humanEvidence) {
  throw new Error('لم يكتب المراجع مادة علمية بعد رقم المراجعة.');
}

return [{
  json: {
    review_id: reviewId,
    reviewer_reference: firstLine,

    human_evidence: humanEvidence,

    reviewer_chat_id: String(data.message.chat.id),
    reviewer_user_id: String(data.message.from.id),
    reviewer_message_id: String(data.message.message_id),

    received_at: new Date().toISOString()
  }
}];

