const verificationRaw = $input.first().json.text;

let verification;
try {
  verification = JSON.parse(verificationRaw);
} catch (e) {
  throw new Error('تعذر قراءة نتيجة التحقق من الإجابة البشرية.');
}

if (verification.verification !== 'PASS') {
  throw new Error(
    `فشل التحقق من الإجابة البشرية: ${verification.reason || 'سبب غير محدد'}`
  );
}

// قراءة الإجابة التي صاغها النموذج في العقدة السابقة
const answerRaw = $('Generate Human Reviewed Answer').first().json.text;

let answer;
try {
  answer = JSON.parse(answerRaw);
} catch (e) {
  throw new Error('تعذر قراءة الإجابة العربية الناتجة بعد المراجعة البشرية.');
}

// استرجاع بيانات حالة المراجعة
const reviewCase = $('Update Human Review Case').first().json;

return [{
  json: {
    review_id: reviewCase.review_id,
    question: reviewCase.question,
    requester_chat_id: String(reviewCase.requester_chat_id),
    requester_message_id: String(reviewCase.requester_message_id),
    target_language: reviewCase.target_language || 'ti',

    answer_ar: answer.answer_ar,

    verification: verification.verification,
    verification_reason: verification.reason,

    evidence_source: 'HUMAN_REVIEW',
    human_review_grounded: true,
    ready_for_translation: true
  }
}];

const item = $input.first().json;

// ==========================================
// 1) قراءة مخرج نموذج تصحيح الترجمة
// ==========================================

let raw = item.output ?? item.text ?? '';

let answerTi = '';


// ==========================================
// 2) إذا كان المخرج Object بالفعل
// ==========================================

if (raw && typeof raw === 'object') {

  answerTi = String(
    raw.answer_ti ??
    raw.translation ??
    ''
  ).trim();

}


// ==========================================
// 3) إذا كان المخرج نصًا
// ==========================================

else {

  raw = String(raw ?? '').trim();

  // إزالة Markdown fences إن وجدت
  raw = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();


  // ----------------------------------------
  // المحاولة الأولى: JSON طبيعي
  // ----------------------------------------

  try {

    const parsed = JSON.parse(raw);

    answerTi = String(
      parsed.answer_ti ??
      parsed.translation ??
      ''
    ).trim();

  } catch (error) {

    // --------------------------------------
    // المحاولة الثانية:
    // استخراج answer_ti مباشرة من النص
    // حتى إذا احتوى JSON على أسطر غير مهربة
    // --------------------------------------

    const match = raw.match(
      /"answer_ti"\s*:\s*"([\s\S]*)"\s*}\s*$/
    );

    if (match && match[1]) {

      answerTi = match[1]
        .replace(/\\"/g, '"')
        .replace(/\\n/g, '\n')
        .replace(/\\r/g, '\r')
        .replace(/\\t/g, '\t')
        .replace(/\\\\/g, '\\')
        .trim();

    }

  }

}


// ==========================================
// 4) التحقق
// ==========================================

if (!answerTi) {

  throw new Error(
    'لم يتم العثور على answer_ti في الترجمة التغرينية المصححة.'
  );

}


// ==========================================
// 5) استرجاع بيانات الترجمة السابقة
// ==========================================

let previousData = {};

try {

  previousData =
    $('Parse Translation Verification').first().json;

} catch (error) {

  previousData = {};

}


// ==========================================
// 6) إخراج النسخة المصححة للتحقق الثاني
// ==========================================

return [{
  json: {

    ...previousData,

    answer_ti: answerTi,

    translation_attempt:
      Number(previousData.translation_attempt ?? 1) + 1,

    is_revised_translation: true,

    translation_verified: false,

    action: null,

    translation_reason: '',

    meaning_issues: [],

    omissions: [],

    additions: [],

    terminology_issues: [],

    citation_issues: [],

    ready_for_translation_verification: true

  }
}];

const item = $input.first().json;

// ==========================================
// 1) قراءة الترجمة الخارجة من النموذج
// ==========================================

let raw = item.output ?? item.text ?? '';
let answerTi = '';


// ==========================================
// 2) إذا كان الناتج Object جاهزًا
// ==========================================

if (raw && typeof raw === 'object') {

  answerTi = String(
    raw.answer_ti ??
    raw.translation ??
    ''
  ).trim();

}


// ==========================================
// 3) إذا كان الناتج String
// ==========================================

else {

  raw = String(raw ?? '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();


  // المحاولة الأولى:
  // JSON سليم
  try {

    const parsed = JSON.parse(raw);

    answerTi = String(
      parsed.answer_ti ??
      parsed.translation ??
      ''
    ).trim();

  } catch (error) {

    // ======================================
    // المحاولة الاحتياطية:
    // استخراج answer_ti حتى لو احتوى JSON
    // على أسطر فعلية غير مهربة
    // ======================================

    const match = raw.match(
      /"answer_ti"\s*:\s*"([\s\S]*)"\s*}\s*$/
    );

    if (match && match[1]) {

      answerTi = match[1]
        .replace(/\\"/g, '"')
        .replace(/\\n/g, '\n')
        .replace(/\\r/g, '\r')
        .replace(/\\t/g, '\t')
        .replace(/\\\\/g, '\\')
        .trim();

    }

  }

}


// ==========================================
// 4) التحقق من وجود الترجمة
// ==========================================

if (!answerTi) {

  throw new Error(
    'لم يتم العثور على الترجمة التغرينية في مخرج نموذج الترجمة.'
  );

}


// ==========================================
// 5) استرجاع سياق الإجابة الأصلية
// ==========================================

let sourceData = {};


// المسار الآلي
try {

  const automated =
    $('Prepare Verified Answer')
      .first()
      .json;

  if (automated?.answer_ar) {
    sourceData = automated;
  }

} catch (error) {}


// المسار بعد المراجعة العلمية البشرية
if (!sourceData.answer_ar) {

  try {

    const humanReviewed =
      $('Prepare Human Reviewed Answer')
        .first()
        .json;

    if (humanReviewed?.answer_ar) {
      sourceData = humanReviewed;
    }

  } catch (error) {}

}


// ==========================================
// 6) استرجاع بيانات السؤال الأصلي
// ==========================================

let incomingData = {};

try {

  incomingData =
    $('Prepare Incoming Question')
      .first()
      .json;

} catch (error) {

  incomingData = {};

}


// ==========================================
// 7) تحديد Chat ID
// ==========================================

const chatId =
  sourceData.chat_id ??
  sourceData.requester_chat_id ??
  incomingData.chat_id ??
  incomingData.requester_chat_id ??
  null;


// ==========================================
// 8) الحفاظ على المصادر
// ==========================================

const sourcesUsed =
  Array.isArray(sourceData.sources_used)
    ? sourceData.sources_used
    : [];


// ==========================================
// 9) إخراج السياق الكامل
// ==========================================

return [{
  json: {

    ...sourceData,

    question:
      sourceData.question ??
      incomingData.question ??
      '',

    chat_id:
      chatId !== null
        ? String(chatId)
        : null,

    message_id:
      sourceData.message_id ??
      sourceData.requester_message_id ??
      incomingData.message_id ??
      null,

    user_id:
      sourceData.user_id ??
      incomingData.user_id ??
      null,

    target_language:
      sourceData.target_language ??
      incomingData.target_language ??
      'ti',

    answer_ar:
      String(sourceData.answer_ar ?? '').trim(),

    answer_ti:
      answerTi,

    // مهم جدًا:
    // لا نفقد المصادر أثناء الانتقال لمسار الترجمة
    sources_used:
      sourcesUsed,

    translation_attempt:
      Number(
        sourceData.translation_attempt ?? 1
      ),

    ready_for_translation_verification:
      true

  }
}];

const data = $input.first().json;

// ========================================
// 1) تجهيز النطاقات المعتمدة
// ========================================

const approvedDomains = Array.isArray(data.approved_domains)
  ? data.approved_domains
      .map(domain =>
        String(domain ?? '')
          .trim()
          .toLowerCase()
          .replace(/^www\./i, '')
      )
      .filter(Boolean)
  : [];

// ========================================
// 2) قراءة نتائج البحث الخارجي
// ========================================

const results = Array.isArray(data.external_evidence)
  ? data.external_evidence
  : [];

// ========================================
// 3) توحيد اسم النطاق
// ========================================

function normalizeDomain(domain) {
  return String(domain ?? '')
    .trim()
    .toLowerCase()
    .replace(/^www\./i, '');
}

// ========================================
// 4) استخراج النطاق من الرابط
// ========================================

function getDomain(url) {
  if (!url) {
    return null;
  }

  try {
    const urlString = String(url).trim();

    const match = urlString.match(
      /^https?:\/\/([^\/?#]+)/i
    );

    if (!match || !match[1]) {
      return null;
    }

    return normalizeDomain(
      match[1].split(':')[0]
    );

  } catch (error) {
    return null;
  }
}

// ========================================
// 5) التحقق من النطاق
// ========================================

function isApprovedDomain(resultDomain) {
  if (!resultDomain) {
    return false;
  }

  const normalized =
    normalizeDomain(resultDomain);

  return approvedDomains.some(domain => {
    const approved =
      normalizeDomain(domain);

    return (
      normalized === approved ||
      normalized.endsWith('.' + approved)
    );
  });
}

// ========================================
// 6) فحص النتائج
// ========================================

const validatedResults = [];
const rejectedResults = [];

for (const result of results) {

  if (!result || typeof result !== 'object') {
    continue;
  }

  const url = String(
    result.url ??
    result.source_url ??
    result.link ??
    ''
  ).trim();

  const title = String(
    result.title ?? ''
  ).trim();

  const content = String(
    result.content ?? ''
  ).trim();

  const domain = getDomain(url);

  const normalizedResult = {
    title,
    url,
    source_url: url,
    content,
    source_domain: domain ?? ''
  };

  // ------------------------------
  // رابط غير صالح
  // ------------------------------

  if (!domain) {
    rejectedResults.push({
      ...normalizedResult,
      rejection_reason:
        'INVALID_OR_MISSING_URL'
    });

    continue;
  }

  // ------------------------------
  // نطاق غير معتمد
  // ------------------------------

  if (!isApprovedDomain(domain)) {
    rejectedResults.push({
      ...normalizedResult,
      rejection_reason:
        'DOMAIN_NOT_APPROVED'
    });

    continue;
  }

  // ------------------------------
  // لا يوجد محتوى
  // ------------------------------

  if (!content) {
    rejectedResults.push({
      ...normalizedResult,
      rejection_reason:
        'EMPTY_CONTENT'
    });

    continue;
  }

  // ------------------------------
  // نتيجة مقبولة
  // ------------------------------

  validatedResults.push(
    normalizedResult
  );
}

// ========================================
// 7) الحالة النهائية
// ========================================

const hasValidResults =
  validatedResults.length > 0;

// ========================================
// 8) الإخراج
// ========================================

return [{
  json: {

    question:
      data.question ?? '',

    chat_id:
      data.chat_id ?? null,

    message_id:
      data.message_id ?? null,

    user_id:
      data.user_id ?? null,

    target_language:
      data.target_language ?? 'ti',

    search_intent:
      data.search_intent ?? '',

    search_status:
      hasValidResults
        ? 'FOUND'
        : 'NOT_FOUND',

    approved_domains:
      approvedDomains,

    approved_urls:
      Array.isArray(data.approved_urls)
        ? data.approved_urls
        : [],

    selected_sources:
      Array.isArray(data.selected_sources)
        ? data.selected_sources
        : [],

    external_evidence:
      validatedResults,

    validated_results_count:
      validatedResults.length,

    rejected_results_count:
      rejectedResults.length,

    rejected_results:
      rejectedResults,

    validation_status:
      hasValidResults
        ? 'VALID'
        : 'NO_VALID_APPROVED_RESULTS',

    needs_human_review:
      !hasValidResults
  }
}];

