const rerank = $input.first().json;

// ---------------------------------
// البيانات الأصلية بعد التحقق البرمجي
// ---------------------------------

let sourceData = {};

try {
  sourceData =
    $('Validate Approved Search Results').first().json;
} catch (error) {
  sourceData = {};
}

// ---------------------------------
// النتائج الأصلية الموثقة
// ---------------------------------

const originalResults =
  Array.isArray(sourceData.external_evidence)
    ? sourceData.external_evidence
    : [];

// ---------------------------------
// نتائج Cohere Rerank
// ---------------------------------

const reranked =
  Array.isArray(rerank.results)
    ? rerank.results
    : [];

// ---------------------------------
// إعادة ربط نتيجة Cohere بالمصدر الأصلي
// ---------------------------------

const externalEvidence = reranked
  .map((result, rank) => {

    const index =
      Number(result.index);

    if (
      !Number.isInteger(index) ||
      index < 0 ||
      index >= originalResults.length
    ) {
      return null;
    }

    const original =
      originalResults[index];

    if (!original) {
      return null;
    }

    const sourceUrl = String(
      original.source_url ??
      original.url ??
      ''
    ).trim();

    return {

      source_layer:
        'APPROVED_EXTERNAL_SOURCE',

      source_type:
        'web',

      rank:
        rank + 1,

      relevance_score:
        Number(
          result.relevance_score ?? 0
        ),

      title:
        String(
          original.title ?? ''
        ).trim(),

      content:
        String(
          original.content ?? ''
        ).trim(),

      source_url:
        sourceUrl,

      url:
        sourceUrl,

      source_domain:
        String(
          original.source_domain ?? ''
        ).trim(),

      source_verified:
        true
    };
  })
  .filter(
    evidence =>
      evidence &&
      evidence.content &&
      evidence.source_url
  );

// ---------------------------------
// أفضل درجة Rerank
// ---------------------------------

const bestExternalScore =
  externalEvidence.length > 0
    ? Math.max(
        ...externalEvidence.map(
          evidence =>
            Number(
              evidence.relevance_score ?? 0
            )
        )
      )
    : 0;

// ---------------------------------
// الإخراج الموحد
// ---------------------------------

return [{
  json: {

    question:
      sourceData.question ?? '',

    chat_id:
      sourceData.chat_id ?? null,

    message_id:
      sourceData.message_id ?? null,

    user_id:
      sourceData.user_id ?? null,

    target_language:
      sourceData.target_language ?? 'ti',

    search_intent:
      sourceData.search_intent ?? '',

    external_evidence:
      externalEvidence,

    external_evidence_count:
      externalEvidence.length,

    best_external_score:
      bestExternalScore,

    approved_domains:
      Array.isArray(
        sourceData.approved_domains
      )
        ? sourceData.approved_domains
        : [],

    approved_urls:
      Array.isArray(
        sourceData.approved_urls
      )
        ? sourceData.approved_urls
        : [],

    selected_sources:
      Array.isArray(
        sourceData.selected_sources
      )
        ? sourceData.selected_sources
        : [],

    evidence_source:
      'APPROVED_EXTERNAL_SEARCH',

    source_validation_passed:
      externalEvidence.length > 0
  }
}];

const externalData = $input.first().json;

// ---------------------------------
// الأدلة الخارجية المعتمدة
// القادمة من Build External Evidence
// ---------------------------------

const externalEvidence =
  Array.isArray(externalData.external_evidence)
    ? externalData.external_evidence
    : [];

// ---------------------------------
// التحقق من وجود أدلة فعلية
// ---------------------------------

if (externalEvidence.length === 0) {
  throw new Error(
    'لم تصل أدلة خارجية صالحة من Build External Evidence.'
  );
}

// ---------------------------------
// إخراج موحد لـ Final Evidence Judge
// ---------------------------------

return [{
  json: {

    question:
      externalData.question ?? '',

    chat_id:
      externalData.chat_id ?? null,

    message_id:
      externalData.message_id ?? null,

    user_id:
      externalData.user_id ?? null,

    target_language:
      externalData.target_language ?? 'ti',

    search_intent:
      externalData.search_intent ?? '',

    // الأدلة التي سيقيّمها Final Evidence Judge
    combined_evidence:
      externalEvidence,

    evidence:
      externalEvidence,

    evidence_count:
      externalEvidence.length,

    external_evidence:
      externalEvidence,

    external_evidence_count:
      externalEvidence.length,

    best_external_score:
      externalData.best_external_score ?? 0,

    approved_domains:
      Array.isArray(externalData.approved_domains)
        ? externalData.approved_domains
        : [],

    approved_urls:
      Array.isArray(externalData.approved_urls)
        ? externalData.approved_urls
        : [],

    selected_sources:
      Array.isArray(externalData.selected_sources)
        ? externalData.selected_sources
        : [],

    evidence_layers: [
      'APPROVED_EXTERNAL_SOURCE'
    ],

    external_search_completed: true,

    evidence_source:
      'APPROVED_EXTERNAL_SEARCH'
  }
}];

const item = $input.first().json;

// ---------------------------------
// قراءة مخرجات Final Evidence Judge
// ---------------------------------

let raw =
  item.text ??
  item.output ??
  '';

if (typeof raw === 'string') {
  raw = raw
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');
}

// ---------------------------------
// تحليل قرار المقيم
// ---------------------------------

let decision;

try {

  decision =
    typeof raw === 'object'
      ? raw
      : JSON.parse(raw);

} catch (error) {

  // Fail-safe:
  // إذا تعذر فهم قرار المقيم النهائي
  // لا نسمح بتوليد إجابة آلية.

  decision = {
    evidence_sufficient: false,
    confidence: 0,
    decision: 'NEEDS_HUMAN_REVIEW',
    needs_human_review: true,

    reason:
      'تعذر قراءة قرار التقييم النهائي للأدلة الخارجية.',

    supported_points: [],
    missing_points: []
  };
}

// ---------------------------------
// القرارات المسموح بها
// ---------------------------------

const allowedDecisions = [
  'SUPPORTED',
  'NEEDS_HUMAN_REVIEW'
];

let finalDecision =
  String(
    decision.decision ?? ''
  )
    .trim()
    .toUpperCase();

// ---------------------------------
// حماية من أي قرار غير معروف
// ---------------------------------

if (
  !allowedDecisions.includes(
    finalDecision
  )
) {

  finalDecision =
    'NEEDS_HUMAN_REVIEW';

  decision.evidence_sufficient =
    false;

  decision.needs_human_review =
    true;

  decision.reason =
    decision.reason ||
    'أعاد المقيم النهائي قرارًا غير معتمد.';
}

// ---------------------------------
// فرض الاتساق المنطقي
// ---------------------------------

const evidenceSufficient =
  finalDecision === 'SUPPORTED';

const needsHumanReview =
  finalDecision ===
  'NEEDS_HUMAN_REVIEW';

// ---------------------------------
// استرجاع الأدلة الخارجية الأصلية
// من العقدة الفعلية الحالية
// ---------------------------------

let evidenceData = {};

try {

  evidenceData =
    $('Build External Evidence')
      .first()
      .json;

} catch (error) {

  evidenceData = {};
}

// ---------------------------------
// الأدلة الخارجية
// ---------------------------------

const externalEvidence =
  Array.isArray(
    evidenceData.external_evidence
  )
    ? evidenceData.external_evidence
    : [];

// ---------------------------------
// إخراج موحد للمسار التالي
// ---------------------------------

return [{
  json: {

    question:
      evidenceData.question ?? '',

    chat_id:
      evidenceData.chat_id ?? null,

    message_id:
      evidenceData.message_id ?? null,

    user_id:
      evidenceData.user_id ?? null,

    target_language:
      evidenceData.target_language ?? 'ti',

    search_intent:
      evidenceData.search_intent ?? '',

    // نحول الأدلة الخارجية إلى الاسم
    // الذي يتوقعه مسار توليد الإجابة
    combined_evidence:
      externalEvidence,

    external_evidence:
      externalEvidence,

    external_evidence_count:
      externalEvidence.length,

    best_external_score:
      Number(
        evidenceData.best_external_score ??
        0
      ),

    approved_domains:
      Array.isArray(
        evidenceData.approved_domains
      )
        ? evidenceData.approved_domains
        : [],

    approved_urls:
      Array.isArray(
        evidenceData.approved_urls
      )
        ? evidenceData.approved_urls
        : [],

    selected_sources:
      Array.isArray(
        evidenceData.selected_sources
      )
        ? evidenceData.selected_sources
        : [],

    evidence_source:
      'APPROVED_EXTERNAL_SEARCH',

    evidence_sufficient:
      evidenceSufficient,

    confidence:
      Number(
        decision.confidence ?? 0
      ),

    decision:
      finalDecision,

    needs_human_review:
      needsHumanReview,

    decision_reason:
      String(
        decision.reason ?? ''
      ).trim(),

    supported_points:
      Array.isArray(
        decision.supported_points
      )
        ? decision.supported_points
        : [],

    missing_points:
      Array.isArray(
        decision.missing_points
      )
        ? decision.missing_points
        : [],

    final_evidence_evaluated:
      true
  }
}];

