const input = $input.first().json;

// ==========================================
// 1) قراءة الإجابة المصححة
// ==========================================

let raw = input.output ?? input.text ?? '';
let revised;

if (typeof raw === 'string') {
  raw = raw
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');
}

try {
  revised =
    typeof raw === 'object'
      ? raw
      : JSON.parse(raw);
} catch (error) {
  throw new Error(
    'تعذر قراءة الإجابة العربية المصححة: ' +
    error.message
  );
}

if (!revised.answer_ar) {
  throw new Error(
    'لم يتم العثور على answer_ar في الإجابة المصححة.'
  );
}


// ==========================================
// 2) استرجاع بيانات الإجابة السابقة
// وتقرير التحقق
// ==========================================

const previousData =
  $('Parse Answer Verification').first().json;


// ==========================================
// 3) تنظيف وتوحيد المصادر المصححة
// ==========================================

// مهم:
// إذا أعاد المراجع sources_used فارغة، نحترم ذلك.
// لا نعيد المصادر القديمة تلقائيًا.

const revisedSources =
  Array.isArray(revised.sources_used)
    ? revised.sources_used
        .filter(source =>
          source &&
          typeof source === 'object'
        )
        .map(source => {

          let sourceType = String(
            source.source_type ?? ''
          )
            .trim()
            .toLowerCase();

          if (
            !['book', 'web', 'turath'].includes(sourceType)
          ) {
            sourceType = '';
          }

          return {
            source_type: sourceType,

            title:
              String(source.title ?? '').trim(),

            author:
              String(source.author ?? '').trim(),

            page:
              String(source.page ?? '').trim(),

            url:
              String(
                source.url ??
                source.source_url ??
                ''
              ).trim()
          };
        })
        .filter(source =>
          source.title ||
          source.author ||
          source.page ||
          source.url
        )
    : [];


// ==========================================
// 4) إخراج الإجابة المصححة
// ==========================================

return [{
  json: {
    ...previousData,

    // الإجابة المصححة الموجهة مباشرة للمدعو
    answer_ar:
      String(revised.answer_ar).trim(),

    // المصادر المستخدمة فعليًا فقط
    sources_used:
      revisedSources,

    grounded:
      revised.grounded === true,

    // زيادة عدد محاولات التصحيح
    answer_revision_attempt:
      Number(
        previousData.answer_revision_attempt ?? 0
      ) + 1,

    // تنظيف نتيجة التحقق السابقة
    verification: null,
    verification_confidence: null,
    verification_reason: '',
    unsupported_claims: [],
    required_corrections: [],

    // إعادة إرسال الإجابة إلى المدقق
    ready_for_verification: true
  }
}];

const data = $input.first().json;

const reviewId =
  `TR-${data.chat_id || data.requester_chat_id || 'unknown'}-${Date.now()}`;

return [{
  json: {
    ...data,

    translation_review_id: reviewId,

    translation_review_status: 'WAITING_FOR_HUMAN',

