// ==========================================

let evidenceData = {};

// أولاً نحاول أخذ البيانات الحالية
if (
  Array.isArray(data.combined_evidence) &&
  data.combined_evidence.length > 0
) {
  evidenceData = data;
}


// إذا لم توجد، نأخذها من Combine Evidence
if (
  !Array.isArray(evidenceData.combined_evidence) ||
  evidenceData.combined_evidence.length === 0
) {
  try {
    const combined =
      $('Combine Evidence').first().json;

    if (
      Array.isArray(combined.combined_evidence) &&
      combined.combined_evidence.length > 0
    ) {
      evidenceData = combined;
    }
  } catch (error) {
    // نكمل
  }
}


// إذا كان القرار بعد البحث الخارجي
// نستخدم Combine External Evidence
try {
  const external =
    $('Combine External Evidence').first().json;

  if (
    Array.isArray(external.combined_evidence) &&
    external.combined_evidence.length > 0
  ) {
    evidenceData = external;
  }
} catch (error) {
  // هذا طبيعي إذا لم يعمل البحث الخارجي
}


// ==========================================
// 3) تحديد الأدلة النهائية
// ==========================================

const combinedEvidence =
  Array.isArray(data.combined_evidence) &&
  data.combined_evidence.length > 0
    ? data.combined_evidence
    : Array.isArray(evidenceData.combined_evidence)
      ? evidenceData.combined_evidence
      : [];


// ==========================================
// 4) بيانات قرار Evidence Judge
// ==========================================

const supportedPoints =
