    ? data.supported_points
    : [];

const missingPoints =
  Array.isArray(data.missing_points)
    ? data.missing_points
    : [];


// ==========================================
// 5) إخراج السياق الكامل
// ==========================================

return [{
  json: {

    // بيانات السائل
    question:
      data.question ??
      incoming.question ??
      '',

    chat_id:
      data.chat_id ??
      data.requester_chat_id ??
      incoming.chat_id ??
      null,

    message_id:
      data.message_id ??
      data.requester_message_id ??
      incoming.message_id ??
      null,

    user_id:
      data.user_id ??
      incoming.user_id ??
      null,

    target_language:
      data.target_language ??
      incoming.target_language ??
      'ti',

    // الأدلة
    combined_evidence:
      combinedEvidence,

    supported_points:
      supportedPoints,

    missing_points:
      missingPoints,

    // قرار كفاية الأدلة
    evidence_sufficient:
      data.evidence_sufficient ?? true,

    confidence:
      data.confidence ?? null,

    decision:
      data.decision ?? 'SUPPORTED',

    // التحكم في التصحيح
    answer_revision_attempt:
      Number(data.answer_revision_attempt ?? 0)
  }
}];

