        external_evidence_count: 0,

        routing_reason:
          'لم يتم العثور على نطاق معتمد مناسب لإجراء البحث الخارجي.'
      }
    }
  ];
}

// توجد نطاقات معتمدة.
// أنشئ Item مستقلًا لكل نطاق حتى يبحث Tavily داخله.
return domains.map(domain => ({
  json: {
    ...data,

    approved_domain: domain.trim(),

    search_query:
      `${data.question || ''} ${data.search_intent || ''}`.trim(),

    search_status: 'READY_FOR_APPROVED_SEARCH',

    can_search: true,

    needs_human_review: false
  }
}));

const data = $input.first().json;


// ==========================================
// 1) السماح فقط بالإجابة التي نجحت في التحقق
// ==========================================

if (data.verification !== 'PASS') {
  throw new Error(
    `لا يمكن تجهيز الإجابة للترجمة لأن نتيجة التحقق هي: ${data.verification || 'UNKNOWN'}`
  );
}

const answerAr = String(data.answer_ar ?? '').trim();

if (!answerAr) {
  throw new Error(
    'لا توجد إجابة عربية موثقة لإرسالها إلى الترجمة.'
  );
}


// ==========================================
// 2) الحفاظ على المصادر الموثقة
// ==========================================

const sourcesUsed =
  Array.isArray(data.sources_used)
    ? data.sources_used
        .filter(source =>
          source &&
          typeof source === 'object'
        )
        .map(source => ({
          source_type:
            String(
              source.source_type ?? ''
            ).trim(),

          title:
            String(
              source.title ?? ''
            ).trim(),

          author:
            String(
              source.author ?? ''
            ).trim(),

          page:
            String(
              source.page ??
              source.pages ??
              ''
            ).trim(),

          url:
            String(
              source.url ??
              source.source_url ??
              ''
            ).trim()
        }))
    : [];


// ==========================================
// 3) الحفاظ على مصدر الأدلة الحقيقي
// ==========================================

let evidenceSource =
  String(
    data.evidence_source ??
    ''
  ).trim();


// إذا لم تصل قيمة صريحة، نحاول استنتاجها
// فقط من البيانات الموجودة فعليًا

if (!evidenceSource) {

  // مراجعة بشرية
  if (
    data.human_review_grounded === true ||
    data.review_id ||
    data.human_review_status === 'APPROVED'
  ) {

    evidenceSource = 'HUMAN_REVIEW';


  // مصادر خارجية معتمدة
  } else if (
    data.source_validation_passed === true ||
    data.external_evidence_count > 0
  ) {

    evidenceSource = 'APPROVED_EXTERNAL_SEARCH';


  // أدلة من قاعدة المعرفة الداخلية
  } else if (
    sourcesUsed.length > 0
  ) {

    evidenceSource = 'INTERNAL_RAG';


  // غير معروف
  } else {

    evidenceSource = 'UNKNOWN';
  }
}


// ==========================================
// 4) تجهيز الإجابة للترجمة
// ==========================================

return [{
  json: {

    // بيانات الطلب
    question:
      data.question ?? '',

    chat_id:
      data.chat_id ??
      data.requester_chat_id ??
      null,

    message_id:
      data.message_id ??
      data.requester_message_id ??
      null,

    user_id:
      data.user_id ??
      null,

    target_language:
      data.target_language ?? 'ti',


    // الإجابة العربية النهائية الموجهة للمدعو
    answer_ar:
      answerAr,


    // المصادر المخصصة للتحقق البشري
    sources_used:
      sourcesUsed,


    // نتيجة التحقق
    verification:
      data.verification,

    verification_confidence:
      Number(
        data.verification_confidence ?? 0
      ),

    verification_reason:
      data.verification_reason ?? '',


    // ======================================
    // مصدر الأدلة الحقيقي
    // ======================================

    evidence_source:
      evidenceSource,

    grounded:
      data.grounded === true,

    human_review_grounded:
      data.human_review_grounded === true,

    source_validation_passed:
      data.source_validation_passed === true,

    external_evidence_count:
      Number(
        data.external_evidence_count ?? 0
      ),


    // ======================================
    // تجهيز مرحلة الترجمة
    // ======================================

    ready_for_translation:
      true,

    translation_attempt:
      1
  }
}];

const data = $input.first().json;

return [
  {
    json: {
      ...data,

      question: data.question || '',

      decision: 'NEEDS_HUMAN_REVIEW',

      evidence_sufficient: false,

      needs_human_review: true,

      confidence: 1,

      reason:
        data.routing_reason ||
        'لم يتم العثور على مصدر معتمد مناسب يمكن البحث فيه للإجابة عن السؤال.',

      supported_points: [],

      missing_points: [
        'لا توجد أدلة كافية من المصادر المعتمدة المتاحة للإجابة الآلية عن السؤال.'
      ],

      combined_evidence: [],

      external_evidence: [],

      external_evidence_count: 0,

      evidence_source: 'NO_APPROVED_EXTERNAL_SOURCE',

      search_status: 'NO_APPROVED_DOMAINS'
    }
  }
];

const data = $input.first().json;

const question = String(
  data.question ??
  data.message?.text ??
  ''
).trim();

const normalized = question
  .toLowerCase()
  .replace(/[ًٌٍَُِّْـ]/g, '')
  .replace(/[!?؟،,.؛:]+/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// رسائل اجتماعية بسيطة وواضحة فقط.
// نتعمد أن تكون القائمة محدودة حتى لا نصنف سؤالًا علميًا بالخطأ.
const simplePatterns = [
  /^(هلا|هلا والله|ياهلا|يا هلا)$/,
  /^(مرحبا|مرحبا بك|اهلا|اهلا وسهلا|أهلا|أهلا وسهلا)$/,
  /^(السلام عليكم|السلام عليكم ورحمة الله|السلام عليكم ورحمة الله وبركاته)$/,
  /^(سلام|سلام عليكم)$/,
  /^(صباح الخير|مساء الخير)$/,
  /^(كيف حالك|كيفك|شلونك|اخبارك|أخبارك)$/,
  /^(شكرا|شكراً|جزاك الله خيرا|جزاك الله خير)$/,
  /^(مع السلامة|في امان الله|في أمان الله)$/
];

const isSimpleMessage = simplePatterns.some(pattern =>
  pattern.test(normalized)
);

return [
  {
    json: {
      ...data,
      question,
      message_class: isSimpleMessage
        ? 'SIMPLE_CONVERSATION'
        : 'KNOWLEDGE_QUESTION',
      requires_knowledge_pipeline: !isSimpleMessage
    }
  }
];

