const items = $input.all();

if (!items.length) {
  throw new Error('لم تصل أي ملفات JSONL من Google Drive.');
}

const output = [];
const seenChunkIds = new Set();

for (let fileIndex = 0; fileIndex < items.length; fileIndex++) {

  const item = items[fileIndex];

  // ==========================================
  // 1) التحقق من وجود الملف Binary
  // ==========================================

  if (!item.binary?.data) {
    throw new Error(
      `الملف رقم ${fileIndex + 1} لا يحتوي على binary property باسم "data".`
    );
  }

  // اسم الملف - إن كان متاحًا
  const fileName =
    item.binary.data.fileName ||
    item.json?.name ||
    `file_${fileIndex + 1}.jsonl`;

  // ==========================================
  // 2) قراءة محتوى الملف
  // ==========================================

  const buffer =
    await this.helpers.getBinaryDataBuffer(
      fileIndex,
      'data'
    );

  const content = buffer
    .toString('utf8')
    .replace(/^\uFEFF/, '')
    .trim();

  if (!content) {
    throw new Error(
      `ملف JSONL فارغ: ${fileName}`
    );
  }

  // ==========================================
  // 3) تقسيم JSONL إلى سجلات
  // ==========================================

  const lines = content
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);

  // ==========================================
  // 4) قراءة وفحص كل Chunk
  // ==========================================

  for (let lineIndex = 0; lineIndex < lines.length; lineIndex++) {

    let record;

    try {
      record = JSON.parse(lines[lineIndex]);
    } catch (error) {
      throw new Error(
        `JSON غير صالح في الملف "${fileName}" ` +
        `عند السطر ${lineIndex + 1}: ${error.message}`
      );
    }

    // ----------------------------------------
    // التحقق من البنية الأساسية
    // ----------------------------------------

    if (!record || typeof record !== 'object' || Array.isArray(record)) {
      throw new Error(
        `السجل في الملف "${fileName}" عند السطر ${lineIndex + 1} ليس JSON Object صالحًا.`
      );
    }

    const chunkId =
      String(record.id || '').trim();

    if (!chunkId) {
      throw new Error(
        `id مفقود في الملف "${fileName}" عند السطر ${lineIndex + 1}.`
      );
    }

    const text =
      String(record.text || '').trim();

    if (!text) {
      throw new Error(
        `text فارغ في Chunk "${chunkId}" داخل الملف "${fileName}".`
      );
    }

    if (
      !record.metadata ||
      typeof record.metadata !== 'object' ||
      Array.isArray(record.metadata)
    ) {
      throw new Error(
        `metadata مفقودة أو غير صالحة في Chunk "${chunkId}".`
      );
    }

    const sourceTitle =
      String(record.metadata.source_title || '').trim();

    if (!sourceTitle) {
      throw new Error(
        `metadata.source_title مفقود في Chunk "${chunkId}".`
      );
    }

    // ==========================================
    // 5) منع تكرار Chunk IDs
    // ==========================================

    if (seenChunkIds.has(chunkId)) {
      throw new Error(
        `Chunk ID مكرر: "${chunkId}". ` +
        `يجب أن يكون كل id فريدًا في جميع ملفات قاعدة المعرفة.`
      );
    }

    seenChunkIds.add(chunkId);

    // ==========================================
    // 6) إخراج Chunk
    // ==========================================

    output.push({
      json: {
        ...record,

        id: chunkId,
        text,

        metadata: {
          ...record.metadata,

          source_title: sourceTitle,

          source_type:
            record.metadata.source_type || 'book',

          language:
            record.metadata.language || 'ar'
        }
      }
    });
  }
}

if (!output.length) {
  throw new Error(
    'لم يتم العثور على أي Chunks صالحة داخل ملفات JSONL.'
  );
}

return output;
